import sys
from itertools import permutations

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
p = 2
INF = float('inf')
d = [[INF] * n for _ in range(n)]
for i in range(n):
    d[i][i] = 0
for _ in range(m):
    u, v, w = int(data[p]), int(data[p + 1]), int(data[p + 2])
    p += 3
    d[u][v] = min(d[u][v], w)
    d[v][u] = min(d[v][u], w)
s, t = int(data[p]), int(data[p + 1])
p += 2
b = int(data[p]); p += 1
banned = set(int(x) for x in data[p:p + b]); p += b
k = int(data[p]); p += 1
req = [int(x) for x in data[p:p + k]]
for x in banned:
    for y in range(n):
        if y != x:
            d[x][y] = INF
            d[y][x] = INF
for mid in range(n):
    if mid in banned:
        continue
    for i in range(n):
        for j in range(n):
            if d[i][mid] + d[mid][j] < d[i][j]:
                d[i][j] = d[i][mid] + d[mid][j]
if s in banned or t in banned or any(r in banned for r in req):
    print(-1)
else:
    best = INF
    for perm in permutations(req):
        cur = s
        total = 0
        for r in perm:
            total += d[cur][r]
            cur = r
        total += d[cur][t]
        best = min(best, total)
    print(best if best < INF else -1)

